// Error hierarchy and source marks, mirroring PyYAML's yaml.error module.

export class Mark {
  constructor(name, index, line, column, buffer, pointer) {
    this.name = name;
    this.index = index;
    this.line = line;
    this.column = column;
    this.buffer = buffer;
    this.pointer = pointer;
  }

  getSnippet(indent = 4, maxLength = 75) {
    if (this.buffer === null || this.buffer === undefined) return null;
    let start = this.pointer;
    let end = this.pointer;
    let head = '';
    let tail = '';
    const breaks = '\0\r\n\x85  ';
    while (start > 0 && !breaks.includes(this.buffer[start - 1])) {
      start -= 1;
      if (this.pointer - start > maxLength / 2 - 1) {
        head = ' ... ';
        start += 5;
        break;
      }
    }
    while (end < this.buffer.length && !breaks.includes(this.buffer[end])) {
      end += 1;
      if (end - this.pointer > maxLength / 2 - 1) {
        tail = ' ... ';
        end -= 5;
        break;
      }
    }
    const snippet = this.buffer.slice(start, end);
    return (
      ' '.repeat(indent) + head + snippet + tail + '\n' +
      ' '.repeat(indent + this.pointer - start + head.length) + '^'
    );
  }

  toString() {
    const snippet = this.getSnippet();
    let where = `  in "${this.name}", line ${this.line + 1}, column ${this.column + 1}`;
    if (snippet !== null) where += ':\n' + snippet;
    return where;
  }
}

export class YAMLError extends Error {
  constructor(message) {
    super(message);
    this.name = 'yaml.error.YAMLError';
  }
}

export class MarkedYAMLError extends YAMLError {
  constructor(context, contextMark, problem, problemMark, note) {
    super('');
    this.context = context ?? null;
    this.contextMark = contextMark ?? null;
    this.problem = problem ?? null;
    this.problemMark = problemMark ?? null;
    this.note = note ?? null;
    this.message = this.buildMessage();
  }

  buildMessage() {
    const lines = [];
    if (this.context !== null) lines.push(this.context);
    if (
      this.contextMark !== null &&
      (this.problem === null ||
        this.problemMark === null ||
        this.contextMark.name !== this.problemMark.name ||
        this.contextMark.line !== this.problemMark.line ||
        this.contextMark.column !== this.problemMark.column)
    ) {
      lines.push(String(this.contextMark));
    }
    if (this.problem !== null) lines.push(this.problem);
    if (this.problemMark !== null) lines.push(String(this.problemMark));
    if (this.note !== null) lines.push(this.note);
    return lines.join('\n');
  }
}

export class ReaderError extends YAMLError {
  constructor(name, position, character, encoding, reason) {
    super('');
    this.pyName = 'yaml.reader.ReaderError';
    this.streamName = name;
    this.position = position;
    this.character = character;
    this.encoding = encoding;
    this.reason = reason;
    this.message =
      `unacceptable character #x${hex(character)}: ${reason}\n` +
      `  in "${name}", position ${position}`;
  }
}

function hex(code) {
  let s = code.toString(16).toUpperCase();
  if (s.length < 4) s = s.padStart(4, '0');
  return s;
}

export class ScannerError extends MarkedYAMLError {
  constructor(...args) {
    super(...args);
    this.pyName = 'yaml.scanner.ScannerError';
  }
}

export class ParserError extends MarkedYAMLError {
  constructor(...args) {
    super(...args);
    this.pyName = 'yaml.parser.ParserError';
  }
}

export class ComposerError extends MarkedYAMLError {
  constructor(...args) {
    super(...args);
    this.pyName = 'yaml.composer.ComposerError';
  }
}

export class ConstructorError extends MarkedYAMLError {
  constructor(...args) {
    super(...args);
    this.pyName = 'yaml.constructor.ConstructorError';
  }
}

export class EmitterError extends YAMLError {
  constructor(message) {
    super(message);
    this.pyName = 'yaml.emitter.EmitterError';
  }
}

export class SerializerError extends YAMLError {
  constructor(message) {
    super(message);
    this.pyName = 'yaml.serializer.SerializerError';
  }
}

export class RepresenterError extends YAMLError {
  constructor(message) {
    super(message);
    this.pyName = 'yaml.representer.RepresenterError';
  }
}

// Stand-in for Python's built-in ValueError, raised by date/time construction.
export class PyValueError extends Error {
  constructor(message) {
    super(message);
    this.pyName = 'ValueError';
  }
}

