// A small model of the Python runtime values that yaml.safe_load can produce.
//
// Mapping of Python types onto JavaScript:
//   None      -> PY_NONE (a unique sentinel)
//   bool      -> boolean
//   int       -> bigint          (arbitrary precision, like Python)
//   float     -> number
//   str       -> string
//   bytes     -> Uint8Array
//   list      -> Array
//   tuple     -> PyTuple
//   dict      -> PyDict
//   set       -> PySet
//   date      -> PyDate
//   datetime  -> PyDateTime

export const PY_NONE = Symbol('None');

export class Unhashable extends Error {}

export class PyTypeError extends Error {
  constructor(message) {
    super(message);
    this.pyName = 'TypeError';
  }
}

export class PyTuple {
  constructor(items) {
    this.items = items;
  }
}

export class PyDate {
  constructor(year, month, day) {
    this.year = year;
    this.month = month;
    this.day = day;
  }

  isoformat() {
    return (
      pad(this.year, 4) + '-' + pad(this.month, 2) + '-' + pad(this.day, 2)
    );
  }
}

export class PyDateTime extends PyDate {
  // `offset` is the utcoffset in minutes, or null for a naive datetime.
  constructor(year, month, day, hour, minute, second, microsecond, offset) {
    super(year, month, day);
    this.hour = hour;
    this.minute = minute;
    this.second = second;
    this.microsecond = microsecond;
    this.offset = offset === undefined ? null : offset;
  }

  isoformat(sep = 'T') {
    let s =
      pad(this.year, 4) + '-' + pad(this.month, 2) + '-' + pad(this.day, 2) +
      sep +
      pad(this.hour, 2) + ':' + pad(this.minute, 2) + ':' + pad(this.second, 2);
    if (this.microsecond) s += '.' + pad(this.microsecond, 6);
    if (this.offset !== null) {
      const sign = this.offset < 0 ? '-' : '+';
      const total = Math.abs(this.offset);
      s += sign + pad(Math.floor(total / 60), 2) + ':' + pad(total % 60, 2);
    }
    return s;
  }
}

function pad(n, width) {
  let s = String(n);
  while (s.length < width) s = '0' + s;
  return s;
}

let nanCounter = 0;
const nanKeys = new WeakMap();

// Python's dict key identity: True == 1, 1 == 1.0, and lists/dicts/sets
// cannot be keys at all.
export function hashKey(value) {
  if (value === PY_NONE) return 'N';
  const t = typeof value;
  if (t === 'boolean') return 'I:' + (value ? '1' : '0');
  if (t === 'bigint') return 'I:' + value.toString();
  if (t === 'number') {
    if (Number.isNaN(value)) {
      // Every distinct NaN object hashes separately in CPython >= 3.10.
      nanCounter += 1;
      return 'F:nan:' + nanCounter;
    }
    if (Number.isFinite(value) && Number.isInteger(value)) {
      return 'I:' + BigInt(value).toString();
    }
    return 'F:' + value;
  }
  if (t === 'string') return 'S:' + value;
  if (value instanceof Uint8Array) {
    let s = 'B:';
    for (const b of value) s += pad(b.toString(16), 2);
    return s;
  }
  if (value instanceof PyTuple) {
    const parts = [];
    for (const item of value.items) parts.push(hashKey(item));
    return 'T(' + parts.join('\x01') + ')';
  }
  if (value instanceof PyDateTime) return 'DT:' + value.isoformat() ;
  if (value instanceof PyDate) return 'D:' + value.isoformat();
  if (value instanceof PySet) {
    throw new Unhashable("unhashable type: 'set'");
  }
  if (value instanceof PyDict) {
    throw new Unhashable("unhashable type: 'dict'");
  }
  if (Array.isArray(value)) {
    throw new Unhashable("unhashable type: 'list'");
  }
  throw new Unhashable('unhashable type');
}

export class PyDict {
  constructor() {
    this.entries = new Map(); // hash -> [key, value]
  }

  get size() {
    return this.entries.size;
  }

  set(key, value) {
    this.entries.set(hashKey(key), [key, value]);
  }

  has(key) {
    return this.entries.has(hashKey(key));
  }

  get(key) {
    const found = this.entries.get(hashKey(key));
    return found === undefined ? undefined : found[1];
  }

  delete(key) {
    return this.entries.delete(hashKey(key));
  }

  // Insertion-ordered [key, value] pairs.
  items() {
    return Array.from(this.entries.values());
  }

  keys() {
    return this.items().map((pair) => pair[0]);
  }

  update(other) {
    for (const [k, v] of other.items()) this.set(k, v);
  }
}

export class PySet {
  constructor() {
    this.members = new Map(); // hash -> key
  }

  get size() {
    return this.members.size;
  }

  add(key) {
    this.members.set(hashKey(key), key);
  }

  values() {
    return Array.from(this.members.values());
  }
}

export function typeName(value) {
  if (value === PY_NONE) return 'NoneType';
  const t = typeof value;
  if (t === 'boolean') return 'bool';
  if (t === 'bigint') return 'int';
  if (t === 'number') return 'float';
  if (t === 'string') return 'str';
  if (value instanceof Uint8Array) return 'bytes';
  if (value instanceof PyTuple) return 'tuple';
  if (value instanceof PyDateTime) return 'datetime.datetime';
  if (value instanceof PyDate) return 'datetime.date';
  if (value instanceof PyDict) return 'dict';
  if (value instanceof PySet) return 'set';
  if (Array.isArray(value)) return 'list';
  return 'object';
}

// ---------------------------------------------------------------- float repr

const NEGATIVE_ZERO_DIGITS = { digits: '0', decpt: 1 };

function shortestDigits(value) {
  // Uses the shortest round-trip decimal expansion, then splits it into a
  // digit string and a decimal-point exponent so that
  //   value = 0.<digits> * 10**decpt
  if (value === 0) return NEGATIVE_ZERO_DIGITS;
  const text = Math.abs(value).toExponential();
  let mantissa = '';
  let exponent = '';
  let seenE = false;
  for (const ch of text) {
    if (ch === 'e') {
      seenE = true;
    } else if (seenE) {
      exponent += ch;
    } else if (ch !== '.') {
      mantissa += ch;
    }
  }
  while (mantissa.length > 1 && mantissa[mantissa.length - 1] === '0') {
    mantissa = mantissa.slice(0, mantissa.length - 1);
  }
  return { digits: mantissa, decpt: Number(exponent) + 1 };
}

// Equivalent of CPython's repr() for a finite float.
export function floatRepr(value) {
  const sign = value < 0 || Object.is(value, -0) ? '-' : '';
  const { digits, decpt } = shortestDigits(value);
  if (decpt <= -4 || decpt > 16) {
    let mantissa = digits[0];
    if (digits.length > 1) mantissa += '.' + digits.slice(1);
    const exp = decpt - 1;
    const expSign = exp < 0 ? '-' : '+';
    let expDigits = String(Math.abs(exp));
    if (expDigits.length < 2) expDigits = '0' + expDigits;
    return sign + mantissa + 'e' + expSign + expDigits;
  }
  if (decpt <= 0) {
    return sign + '0.' + '0'.repeat(-decpt) + digits;
  }
  if (decpt >= digits.length) {
    return sign + digits + '0'.repeat(decpt - digits.length) + '.0';
  }
  return sign + digits.slice(0, decpt) + '.' + digits.slice(decpt);
}

