// Python-compatible ordering: the `<` operator's type rules plus the exact
// comparison sequence of CPython's list.sort() for short lists, so that a
// TypeError surfaces in the same situations that make PyYAML fall back to
// insertion order.

import {
  PY_NONE,
  PyDate,
  PyDateTime,
  PyDict,
  PySet,
  PyTuple,
  PyTypeError,
  typeName,
} from './pytypes.mjs';

const NUMERIC = 'numeric';

function kindOf(value) {
  if (value === PY_NONE) return 'none';
  const t = typeof value;
  if (t === 'boolean' || t === 'bigint' || t === 'number') return NUMERIC;
  if (t === 'string') return 'str';
  if (value instanceof Uint8Array) return 'bytes';
  if (value instanceof PyTuple) return 'tuple';
  if (value instanceof PyDateTime) return 'datetime';
  if (value instanceof PyDate) return 'date';
  if (value instanceof PyDict) return 'dict';
  if (value instanceof PySet) return 'set';
  if (Array.isArray(value)) return 'list';
  return 'object';
}

function unorderable(a, b) {
  return new PyTypeError(
    `'<' not supported between instances of '${typeName(a)}' and '${typeName(b)}'`
  );
}

function toBig(value) {
  if (typeof value === 'boolean') return value ? 1n : 0n;
  return value;
}

function numericLt(a, b) {
  const x = toBig(a);
  const y = toBig(b);
  if (typeof x === 'bigint' && typeof y === 'bigint') return x < y;
  if (typeof x === 'number' && typeof y === 'number') return x < y;
  // Mixed int/float: compare exactly by splitting the float.
  if (typeof x === 'number') {
    if (Number.isNaN(x)) return false;
    if (x === Infinity) return false;
    if (x === -Infinity) return true;
    const whole = BigInt(Math.floor(x));
    if (whole !== y) return whole < y;
    return Math.floor(x) !== x ? false : false;
  }
  if (Number.isNaN(y)) return false;
  if (y === Infinity) return true;
  if (y === -Infinity) return false;
  const whole = BigInt(Math.floor(y));
  if (x !== whole) return x < whole;
  return Math.floor(y) !== y;
}

function bytesLt(a, b) {
  const n = Math.min(a.length, b.length);
  for (let i = 0; i < n; i += 1) {
    if (a[i] !== b[i]) return a[i] < b[i];
  }
  return a.length < b.length;
}

// Python's == for the values safe_load produces; never raises.
export function pyEq(a, b) {
  const ka = kindOf(a);
  const kb = kindOf(b);
  if (ka === NUMERIC && kb === NUMERIC) {
    return !numericLt(a, b) && !numericLt(b, a) && !isNan(a) && !isNan(b);
  }
  if (ka !== kb) return false;
  switch (ka) {
    case 'none':
      return true;
    case 'str':
      return a === b;
    case 'bytes':
      return !bytesLt(a, b) && !bytesLt(b, a);
    case 'tuple':
      return seqEq(a.items, b.items);
    case 'list':
      return seqEq(a, b);
    case 'date':
      return a.isoformat() === b.isoformat();
    case 'datetime':
      return a.isoformat() === b.isoformat();
    default:
      return a === b;
  }
}

function isNan(value) {
  return typeof value === 'number' && Number.isNaN(value);
}

function seqEq(a, b) {
  if (a.length !== b.length) return false;
  for (let i = 0; i < a.length; i += 1) {
    if (!pyEq(a[i], b[i])) return false;
  }
  return true;
}

function seqLt(a, b) {
  const n = Math.min(a.length, b.length);
  for (let i = 0; i < n; i += 1) {
    if (!pyEq(a[i], b[i])) return pyLt(a[i], b[i]);
  }
  return a.length < b.length;
}

export function pyLt(a, b) {
  const ka = kindOf(a);
  const kb = kindOf(b);
  if (ka === NUMERIC && kb === NUMERIC) return numericLt(a, b);
  if (ka !== kb) throw unorderable(a, b);
  switch (ka) {
    case 'str':
      return strLt(a, b);
    case 'bytes':
      return bytesLt(a, b);
    case 'tuple':
      return seqLt(a.items, b.items);
    case 'list':
      return seqLt(a, b);
    case 'date':
      return a.isoformat() < b.isoformat();
    case 'datetime': {
      const naiveA = a.offset === null;
      const naiveB = b.offset === null;
      if (naiveA !== naiveB) {
        throw new PyTypeError(
          "can't compare offset-naive and offset-aware datetimes"
        );
      }
      return datetimeKey(a) < datetimeKey(b);
    }
    default:
      throw unorderable(a, b);
  }
}

function datetimeKey(value) {
  // Minutes since a fixed point, adjusted by the offset, then microseconds.
  const days =
    value.year * 10000000000 + value.month * 100000000 + value.day * 1000000;
  const time =
    value.hour * 3600 + value.minute * 60 + value.second -
    (value.offset === null ? 0 : value.offset * 60);
  return days + time + value.microsecond / 1000000;
}

// Python compares strings by code point, JavaScript by UTF-16 code unit; they
// differ only for astral characters versus U+E000..U+FFFF.
function strLt(a, b) {
  const ca = Array.from(a);
  const cb = Array.from(b);
  const n = Math.min(ca.length, cb.length);
  for (let i = 0; i < n; i += 1) {
    if (ca[i] !== cb[i]) {
      return ca[i].codePointAt(0) < cb[i].codePointAt(0);
    }
  }
  return ca.length < cb.length;
}

function reverseSlice(items, lo, hi) {
  hi -= 1;
  while (lo < hi) {
    const tmp = items[lo];
    items[lo] = items[hi];
    items[hi] = tmp;
    lo += 1;
    hi -= 1;
  }
}

function countRun(items, lo, hi, lt) {
  let descending = false;
  let index = lo + 1;
  if (index === hi) return { n: 1, descending };
  let n = 2;
  if (lt(items[index], items[index - 1])) {
    descending = true;
    for (index += 1; index < hi; index += 1, n += 1) {
      if (!lt(items[index], items[index - 1])) break;
    }
  } else {
    for (index += 1; index < hi; index += 1, n += 1) {
      if (lt(items[index], items[index - 1])) break;
    }
  }
  return { n, descending };
}

function binarySort(items, lo, hi, start, lt) {
  if (lo === start) start += 1;
  for (; start < hi; start += 1) {
    const pivot = items[start];
    let left = lo;
    let right = start;
    while (left < right) {
      const middle = left + ((right - left) >> 1);
      if (lt(pivot, items[middle])) right = middle;
      else left = middle + 1;
    }
    for (let p = start; p > left; p -= 1) items[p] = items[p - 1];
    items[left] = pivot;
  }
}

// CPython's list.sort() for lists shorter than 64 items, which is the only
// regime PyYAML's key sorting realistically hits; longer lists get the same
// stable order from the same primitives.
export function pySort(items, lt) {
  const n = items.length;
  if (n < 2) return;
  let lo = 0;
  let remaining = n;
  const minrun = n < 64 ? n : 32;
  do {
    const { n: runLength, descending } = countRun(items, lo, n, lt);
    let length = runLength;
    if (descending) reverseSlice(items, lo, lo + length);
    if (length < minrun) {
      const force = remaining <= minrun ? remaining : minrun;
      binarySort(items, lo, lo + force, lo + length, lt);
      length = force;
    }
    if (length < remaining) {
      // Merge the sorted prefix with the sorted remainder (stable).
      const rest = items.slice(lo + length);
      pySort(rest, lt);
      const merged = stableMerge(items.slice(lo, lo + length), rest, lt);
      for (let i = 0; i < merged.length; i += 1) items[lo + i] = merged[i];
    }
    remaining -= length;
    lo += length;
  } while (remaining > 0);
}

function stableMerge(left, right, lt) {
  const out = [];
  let i = 0;
  let j = 0;
  while (i < left.length && j < right.length) {
    if (lt(right[j], left[i])) {
      out.push(right[j]);
      j += 1;
    } else {
      out.push(left[i]);
      i += 1;
    }
  }
  while (i < left.length) out.push(left[i++]);
  while (j < right.length) out.push(right[j++]);
  return out;
}

// sorted() over (key, value) pairs, as PyYAML's represent_mapping does.
export function pySortedPairs(pairs) {
  const copy = pairs.slice();
  pySort(copy, (a, b) => {
    if (pyEq(a[0], b[0])) return pyLt(a[1], b[1]);
    return pyLt(a[0], b[0]);
  });
  return copy;
}

