// Error hierarchy and source marks, mirroring PyYAML's yaml.error module.

export class Mark {
  constructor(name, index, line, column, buffer, pointer) {
    this.name = name;
    this.index = index;
    this.line = line;
    this.column = column;
    this.buffer = buffer;
    this.pointer = pointer;
  }

  getSnippet(indent = 4, maxLength = 75) {
    if (this.buffer === null || this.buffer === undefined) return null;
    let start = this.pointer;
    let end = this.pointer;
    let head = '';
    let tail = '';
    const breaks = '\0\r\n\x85  ';
    while (start > 0 && !breaks.includes(this.buffer[start - 1])) {
      start -= 1;
      if (this.pointer - start > maxLength / 2 - 1) {
        head = ' ... ';
        start += 5;
        break;
      }
    }
    while (end < this.buffer.length && !breaks.includes(this.buffer[end])) {
      end += 1;
      if (end - this.pointer > maxLength / 2 - 1) {
        tail = ' ... ';
        end -= 5;
        break;
