// Python's repr() for the small strings that appear in scanner/parser errors.

const SIMPLE_ESCAPES = new Map([
  ['\\', '\\\\'],
  ['\n', '\\n'],
  ['\r', '\\r'],
  ['\t', '\\t'],
]);

function isPrintableForRepr(code) {
  if (code < 0x20 || code === 0x7f) return false;
  if (code >= 0x80 && code <= 0x9f) return false;
  if (code === 0xa0 || code === 0xad) return false;
  if (code >= 0x2000 && code <= 0x200f) return false;
  if (code >= 0x2028 && code <= 0x202f) return false;
  if (code === 0xfeff) return false;
  return true;
}

function hexEscape(code) {
  if (code <= 0xff) return '\\x' + hex(code, 2);
  if (code <= 0xffff) return '\\u' + hex(code, 4);
  return '\\U' + hex(code, 8);
}

function hex(code, width) {
  let s = code.toString(16);
  while (s.length < width) s = '0' + s;
  return s;
}

export function pyRepr(text) {
  const quote = text.includes("'") && !text.includes('"') ? '"' : "'";
  let out = quote;
  for (const ch of text) {
    if (ch === quote) {
      out += '\\' + ch;
    } else if (SIMPLE_ESCAPES.has(ch)) {
      out += SIMPLE_ESCAPES.get(ch);
    } else {
      const code = ch.codePointAt(0);
      out += isPrintableForRepr(code) ? ch : hexEscape(code);
    }
  }
  return out + quote;
}

