// Character-level input, mirroring yaml.reader.Reader for a unicode string.
// Positions count Unicode code points, as Python string indexing does.

import { Mark, ReaderError } from './errors.mjs';

const NEL = String.fromCharCode(0x85);
const LS = String.fromCharCode(0x2028);
const PS = String.fromCharCode(0x2029);
const LINE_BREAKS = '\n\r' + NEL + LS + PS;

function isPrintable(ch) {
  const code = ch.codePointAt(0);
  if (code === 0x09 || code === 0x0a || code === 0x0d) return true;
  if (code >= 0x20 && code <= 0x7e) return true;
  if (code === 0x85) return true;
  if (code >= 0xa0 && code <= 0xd7ff) return true;
  if (code >= 0xe000 && code <= 0xfffd) return true;
  if (code >= 0x10000 && code <= 0x10ffff) return true;
  return false;
}

export class Reader {
  constructor(text) {
    this.name = '<unicode string>';
    this.chars = Array.from(text);
    this.checkPrintable();
    this.chars.push('\0');
    this.pointer = 0;
    this.line = 0;
    this.column = 0;
    this.eof = true;
  }

  get index() {
    return this.pointer;
  }

  checkPrintable() {
    for (let i = 0; i < this.chars.length; i += 1) {
      if (!isPrintable(this.chars[i])) {
        throw new ReaderError(
          '<unicode string>',
          i,
          this.chars[i].codePointAt(0),
          'unicode',
          'special characters are not allowed'
        );
      }
    }
  }

  peek(offset = 0) {
    const index = this.pointer + offset;
    if (index >= this.chars.length) return '\0';
    return this.chars[index];
  }

  prefix(length = 1) {
    const end = Math.min(this.pointer + length, this.chars.length);
    return this.chars.slice(this.pointer, end).join('');
  }

  forward(length = 1) {
    let remaining = length;
    while (remaining > 0) {
      const ch = this.chars[this.pointer];
      this.pointer += 1;
      if (
        LINE_BREAKS.includes(ch) &&
        (ch !== '\r' || this.chars[this.pointer] !== '\n')
      ) {
        this.line += 1;
        this.column = 0;
      } else if (ch !== BOM) {
        this.column += 1;
      }
      remaining -= 1;
    }
  }

  getMark() {
    return new Mark(
      this.name,
      this.pointer,
      this.line,
      this.column,
      this.chars,
      this.pointer
    );
  }
}

