// Event producer, a transliteration of yaml.parser.Parser.
// Parser states are held as method names so that the state stack behaves like
// Python's list of bound methods.

import { ParserError } from './errors.mjs';
import {
  AliasEvent,
  DocumentEndEvent,
  DocumentStartEvent,
  MappingEndEvent,
  MappingStartEvent,
  ScalarEvent,
  SequenceEndEvent,
  SequenceStartEvent,
  StreamEndEvent,
  StreamStartEvent,
} from './events.mjs';
import { pyRepr } from './pyrepr.mjs';
import { Scanner } from './scanner.mjs';
import {
  AliasToken,
  AnchorToken,
  BlockEndToken,
  BlockEntryToken,
  BlockMappingStartToken,
  BlockSequenceStartToken,
  DirectiveToken,
  DocumentEndToken,
  DocumentStartToken,
  FlowEntryToken,
  FlowMappingEndToken,
  FlowMappingStartToken,
  FlowSequenceEndToken,
  FlowSequenceStartToken,
  KeyToken,
  ScalarToken,
  StreamEndToken,
  TagToken,
  ValueToken,
} from './tokens.mjs';

const DEFAULT_TAGS = new Map([
  ['!', '!'],
  ['!!', 'tag:yaml.org,2002:'],
]);

export class Parser extends Scanner {
  constructor(text) {
    super(text);
    this.currentEvent = null;
    this.yamlVersion = null;
    this.tagHandles = new Map();
    this.states = [];
    this.marks = [];
    this.state = 'parseStreamStart';
  }

  // -------------------------------------------------------------- public API

  runState() {
    return this[this.state]();
  }

  checkEvent(...classes) {
    if (this.currentEvent === null && this.state !== null) {
      this.currentEvent = this.runState();
    }
    if (this.currentEvent !== null) {
      if (classes.length === 0) return true;
      for (const cls of classes) {
        if (this.currentEvent instanceof cls) return true;
      }
    }
    return false;
  }

  peekEvent() {
    if (this.currentEvent === null && this.state !== null) {
      this.currentEvent = this.runState();
    }
    return this.currentEvent;
  }

  getEvent() {
    if (this.currentEvent === null && this.state !== null) {
      this.currentEvent = this.runState();
    }
    const value = this.currentEvent;
    this.currentEvent = null;
    return value;
  }

  // ----------------------------------------------------------- stream states

  parseStreamStart() {
    const token = this.getToken();
    this.state = 'parseImplicitDocumentStart';
    return new StreamStartEvent(token.startMark, token.endMark);
  }

  parseImplicitDocumentStart() {
    if (
      !this.checkToken(DirectiveToken, DocumentStartToken, StreamEndToken)
    ) {
      this.tagHandles = new Map(DEFAULT_TAGS);
      const token = this.peekToken();
      const startMark = token.startMark;
      this.states.push('parseDocumentEnd');
      this.state = 'parseBlockNode';
      return new DocumentStartEvent(startMark, startMark, false);
    }
    return this.parseDocumentStart();
  }

  parseDocumentStart() {
    while (this.checkToken(DocumentEndToken)) this.getToken();
    if (!this.checkToken(StreamEndToken)) {
      let token = this.peekToken();
      const startMark = token.startMark;
      const [version, tags] = this.processDirectives();
      if (!this.checkToken(DocumentStartToken)) {
        throw new ParserError(
          null,
          null,
          `expected '<document start>', but found ${pyRepr(this.peekToken().id)}`,
          this.peekToken().startMark
        );
      }
      token = this.getToken();
      const endMark = token.endMark;
      this.states.push('parseDocumentEnd');
      this.state = 'parseDocumentContent';
      return new DocumentStartEvent(startMark, endMark, true, version, tags);
    }
    const token = this.getToken();
    this.state = null;
    return new StreamEndEvent(token.startMark, token.endMark);
  }

  parseDocumentEnd() {
    let token = this.peekToken();
    const startMark = token.startMark;
    let endMark = startMark;
    let explicit = false;
    if (this.checkToken(DocumentEndToken)) {
      token = this.getToken();
      endMark = token.endMark;
      explicit = true;
    }
    this.state = 'parseDocumentStart';
    return new DocumentEndEvent(startMark, endMark, explicit);
  }

  parseDocumentContent() {
    if (
      this.checkToken(
        DirectiveToken,
        DocumentStartToken,
        DocumentEndToken,
        StreamEndToken
      )
    ) {
      const event = this.processEmptyScalar(this.peekToken().startMark);
      this.state = this.states.pop();
      return event;
    }
    return this.parseBlockNode();
  }

  processDirectives() {
    this.yamlVersion = null;
    this.tagHandles = new Map();
    while (this.checkToken(DirectiveToken)) {
      const token = this.getToken();
      if (token.directiveName === 'YAML') {
        if (this.yamlVersion !== null) {
          throw new ParserError(
            null,
            null,
            'found duplicate YAML directive',
            token.startMark
          );
        }
        const [major] = token.value;
        if (major !== 1) {
          throw new ParserError(
            null,
            null,
            'found incompatible YAML document (version 1.* is required)',
            token.startMark
          );
        }
        this.yamlVersion = token.value;
      } else if (token.directiveName === 'TAG') {
        const [handle, prefix] = token.value;
        if (this.tagHandles.has(handle)) {
          throw new ParserError(
            null,
            null,
            `duplicate tag handle ${pyRepr(handle)}`,
            token.startMark
          );
        }
        this.tagHandles.set(handle, prefix);
      }
    }
    let value;
    if (this.tagHandles.size) value = [this.yamlVersion, new Map(this.tagHandles)];
    else value = [this.yamlVersion, null];
    for (const [key, prefix] of DEFAULT_TAGS) {
      if (!this.tagHandles.has(key)) this.tagHandles.set(key, prefix);
    }
    return value;
  }

