      const token = this.getToken();
      endMark = token.endMark;
      let scalarImplicit;
      if ((token.plain && tag === null) || tag === '!') {
        scalarImplicit = [true, false];
      } else if (tag === null) {
        scalarImplicit = [false, true];
      } else {
        scalarImplicit = [false, false];
      }
      this.state = this.states.pop();
      return new ScalarEvent(
        anchor,
        tag,
        scalarImplicit,
        token.value,
        startMark,
        endMark,
        token.style
      );
    }
    if (this.checkToken(FlowSequenceStartToken)) {
      endMark = this.peekToken().endMark;
      this.state = 'parseFlowSequenceFirstEntry';
      return new SequenceStartEvent(anchor, tag, implicit, startMark, endMark, true);
    }
    if (this.checkToken(FlowMappingStartToken)) {
      endMark = this.peekToken().endMark;
      this.state = 'parseFlowMappingFirstKey';
      return new MappingStartEvent(anchor, tag, implicit, startMark, endMark, true);
    }
    if (block && this.checkToken(BlockSequenceStartToken)) {
      endMark = this.peekToken().startMark;
      this.state = 'parseBlockSequenceFirstEntry';
      return new SequenceStartEvent(anchor, tag, implicit, startMark, endMark, false);
    }
    if (block && this.checkToken(BlockMappingStartToken)) {
      endMark = this.peekToken().startMark;
      this.state = 'parseBlockMappingFirstKey';
      return new MappingStartEvent(anchor, tag, implicit, startMark, endMark, false);
    }
    if (anchor !== null || tag !== null) {
      this.state = this.states.pop();
      return new ScalarEvent(
        anchor,
        tag,
        [implicit, false],
        '',
        startMark,
        endMark
      );
    }
    const node = block ? 'block' : 'flow';
    const token = this.peekToken();
    throw new ParserError(
      `while parsing a ${node} node`,
      startMark,
      `expected the node content, but found ${pyRepr(token.id)}`,
      token.startMark
    );
  }

  // -------------------------------------------------------- block collection

  parseBlockSequenceFirstEntry() {
    const token = this.getToken();
    this.marks.push(token.startMark);
    return this.parseBlockSequenceEntry();
  }

  parseBlockSequenceEntry() {
    if (this.checkToken(BlockEntryToken)) {
      const token = this.getToken();
      if (!this.checkToken(BlockEntryToken, BlockEndToken)) {
        this.states.push('parseBlockSequenceEntry');
        return this.parseBlockNode();
      }
      this.state = 'parseBlockSequenceEntry';
      return this.processEmptyScalar(token.endMark);
    }
    if (!this.checkToken(BlockEndToken)) {
      const token = this.peekToken();
      throw new ParserError(
        'while parsing a block collection',
        this.marks[this.marks.length - 1],
        `expected <block end>, but found ${pyRepr(token.id)}`,
        token.startMark
      );
    }
    const token = this.getToken();
    this.state = this.states.pop();
    this.marks.pop();
    return new SequenceEndEvent(token.startMark, token.endMark);
  }

  parseIndentlessSequenceEntry() {
    if (this.checkToken(BlockEntryToken)) {
      const token = this.getToken();
      if (
        !this.checkToken(BlockEntryToken, KeyToken, ValueToken, BlockEndToken)
      ) {
        this.states.push('parseIndentlessSequenceEntry');
        return this.parseBlockNode();
      }
      this.state = 'parseIndentlessSequenceEntry';
      return this.processEmptyScalar(token.endMark);
    }
    const token = this.peekToken();
    this.state = this.states.pop();
    return new SequenceEndEvent(token.startMark, token.startMark);
  }

  parseBlockMappingFirstKey() {
    const token = this.getToken();
    this.marks.push(token.startMark);
    return this.parseBlockMappingKey();
  }

  parseBlockMappingKey() {
    if (this.checkToken(KeyToken)) {
      const token = this.getToken();
      if (!this.checkToken(KeyToken, ValueToken, BlockEndToken)) {
        this.states.push('parseBlockMappingValue');
        return this.parseBlockNodeOrIndentlessSequence();
      }
      this.state = 'parseBlockMappingValue';
      return this.processEmptyScalar(token.endMark);
    }
    if (!this.checkToken(BlockEndToken)) {
      const token = this.peekToken();
      throw new ParserError(
        'while parsing a block mapping',
        this.marks[this.marks.length - 1],
        `expected <block end>, but found ${pyRepr(token.id)}`,
        token.startMark
      );
    }
    const token = this.getToken();
    this.state = this.states.pop();
    this.marks.pop();
    return new MappingEndEvent(token.startMark, token.endMark);
  }

  parseBlockMappingValue() {
    if (this.checkToken(ValueToken)) {
      const token = this.getToken();
      if (!this.checkToken(KeyToken, ValueToken, BlockEndToken)) {
        this.states.push('parseBlockMappingKey');
        return this.parseBlockNodeOrIndentlessSequence();
      }
      this.state = 'parseBlockMappingKey';
      return this.processEmptyScalar(token.endMark);
    }
    this.state = 'parseBlockMappingKey';
    const token = this.peekToken();
    return this.processEmptyScalar(token.startMark);
  }

  // --------------------------------------------------------- flow collection

  parseFlowSequenceFirstEntry() {
    const token = this.getToken();
    this.marks.push(token.startMark);
    return this.parseFlowSequenceEntry(true);
  }

  parseFlowSequenceEntry(first = false) {
    if (!this.checkToken(FlowSequenceEndToken)) {
      if (!first) {
        if (this.checkToken(FlowEntryToken)) {
          this.getToken();
        } else {
          const token = this.peekToken();
          throw new ParserError(
            'while parsing a flow sequence',
            this.marks[this.marks.length - 1],
            `expected ',' or ']', but got ${pyRepr(token.id)}`,
            token.startMark
          );
        }
      }
      if (this.checkToken(KeyToken)) {
        const token = this.peekToken();
        this.state = 'parseFlowSequenceEntryMappingKey';
        return new MappingStartEvent(
          null,
          null,
          true,
          token.startMark,
          token.endMark,
          true
        );
      }
      if (!this.checkToken(FlowSequenceEndToken)) {
        this.states.push('parseFlowSequenceEntry');
        return this.parseFlowNode();
      }
    }
    const token = this.getToken();
    this.state = this.states.pop();
    this.marks.pop();
    return new SequenceEndEvent(token.startMark, token.endMark);
  }

  parseFlowSequenceEntryMappingKey() {
    const token = this.getToken();
    if (!this.checkToken(ValueToken, FlowEntryToken, FlowSequenceEndToken)) {
      this.states.push('parseFlowSequenceEntryMappingValue');
      return this.parseFlowNode();
    }
    this.state = 'parseFlowSequenceEntryMappingValue';
    return this.processEmptyScalar(token.endMark);
  }

  parseFlowSequenceEntryMappingValue() {
    if (this.checkToken(ValueToken)) {
      const token = this.getToken();
      if (!this.checkToken(FlowEntryToken, FlowSequenceEndToken)) {
        this.states.push('parseFlowSequenceEntryMappingEnd');
        return this.parseFlowNode();
      }
      this.state = 'parseFlowSequenceEntryMappingEnd';
      return this.processEmptyScalar(token.endMark);
    }
    this.state = 'parseFlowSequenceEntryMappingEnd';
    const token = this.peekToken();
    return this.processEmptyScalar(token.startMark);
  }

  parseFlowSequenceEntryMappingEnd() {
    this.state = 'parseFlowSequenceEntry';
    const token = this.peekToken();
    return new MappingEndEvent(token.startMark, token.startMark);
  }

  parseFlowMappingFirstKey() {
    const token = this.getToken();
    this.marks.push(token.startMark);
    return this.parseFlowMappingKey(true);
  }

  parseFlowMappingKey(first = false) {
    if (!this.checkToken(FlowMappingEndToken)) {
      if (!first) {
        if (this.checkToken(FlowEntryToken)) {
          this.getToken();
        } else {
          const token = this.peekToken();
          throw new ParserError(
            'while parsing a flow mapping',
            this.marks[this.marks.length - 1],
            `expected ',' or '}', but got ${pyRepr(token.id)}`,
            token.startMark
          );
        }
      }
      if (this.checkToken(KeyToken)) {
