// Implicit tag resolution (yaml.resolver.Resolver) for YAML 1.1.
// The resolvers PyYAML expresses as regular expressions are hand-written
// character scanners here.

const DIGITS = '0123456789';
const HEX = '0123456789abcdefABCDEF';

// A cursor over the scalar being tested.
class Cursor {
  constructor(text) {
    this.text = text;
    this.i = 0;
  }

  get atEnd() {
    return this.i >= this.text.length;
  }

  peek() {
    return this.i < this.text.length ? this.text[this.i] : '';
  }

  // Consumes `literal` if present.
  lit(literal) {
    if (this.text.startsWith(literal, this.i)) {
      this.i += literal.length;
      return true;
    }
    return false;
  }

  // Consumes one character from `set`.
  oneOf(set) {
    const ch = this.peek();
    if (ch !== '' && set.includes(ch)) {
      this.i += 1;
      return ch;
    }
    return '';
  }

  // Consumes between `min` and `max` characters from `set`; returns the run or
  // null when fewer than `min` are available.
  run(set, min, max = Infinity) {
    const start = this.i;
    while (this.i < this.text.length && set.includes(this.text[this.i])) {
      if (this.i - start >= max) break;
      this.i += 1;
    }
    if (this.i - start < min) {
      this.i = start;
      return null;
    }
    return this.text.slice(start, this.i);
  }
}

function tryAlternatives(value, alternatives) {
  for (const alternative of alternatives) {
    const cursor = new Cursor(value);
    if (alternative(cursor) && cursor.atEnd) return true;
  }
  return false;
}

const BOOL_VALUES = new Set([
  'yes', 'Yes', 'YES', 'no', 'No', 'NO',
  'true', 'True', 'TRUE', 'false', 'False', 'FALSE',
  'on', 'On', 'ON', 'off', 'Off', 'OFF',
]);

function matchBool(value) {
  return BOOL_VALUES.has(value);
}

function matchNull(value) {
  return value === '' || value === '~' || value === 'null' ||
    value === 'Null' || value === 'NULL';
}

function matchMerge(value) {
  return value === '<<';
}

function matchValue(value) {
  return value === '=';
}

function matchYaml(value) {
  return value === '!' || value === '&' || value === '*';
}

function sign(cursor) {
  cursor.oneOf('-+');
  return true;
}

// Sexagesimal tail: (:[0-5]?[0-9])+
function sexagesimal(cursor) {
  let count = 0;
  for (;;) {
    const mark = cursor.i;
    if (!cursor.lit(':')) break;
    const part = cursor.run(DIGITS, 1, 2);
    if (part === null || (part.length === 2 && !'012345'.includes(part[0]))) {
      cursor.i = mark;
      break;
    }
    count += 1;
  }
  return count > 0;
}

function matchInt(value) {
  return tryAlternatives(value, [
    // [-+]?0b[0-1_]+
    (c) => sign(c) && c.lit('0b') && c.run('01_', 1) !== null,
    // [-+]?0[0-7_]+
    (c) => sign(c) && c.lit('0') && c.run('01234567_', 1) !== null,
    // [-+]?(0|[1-9][0-9_]*)
    (c) => {
      sign(c);
      if (c.lit('0')) return true;
      if (c.oneOf('123456789') === '') return false;
      c.run(DIGITS + '_', 0);
      return true;
    },
    // [-+]?0x[0-9a-fA-F_]+
    (c) => sign(c) && c.lit('0x') && c.run(HEX + '_', 1) !== null,
    // [-+]?[1-9][0-9_]*(:[0-5]?[0-9])+
    (c) => {
      sign(c);
      if (c.oneOf('123456789') === '') return false;
      c.run(DIGITS + '_', 0);
      return sexagesimal(c);
    },
  ]);
}

// ([eE][-+][0-9]+)?  -- PyYAML requires an explicit exponent sign.
function optionalExponent(cursor) {
  const mark = cursor.i;
  if (cursor.oneOf('eE') === '') return true;
  if (cursor.oneOf('-+') === '' || cursor.run(DIGITS, 1) === null) {
    cursor.i = mark;
  }
  return true;
}

function matchFloat(value) {
  return tryAlternatives(value, [
    // [-+]?[0-9][0-9_]*\.[0-9_]*([eE][-+][0-9]+)?
    (c) => {
      sign(c);
      if (c.oneOf(DIGITS) === '') return false;
      c.run(DIGITS + '_', 0);
      if (!c.lit('.')) return false;
      c.run(DIGITS + '_', 0);
      return optionalExponent(c);
    },
    // \.[0-9_]+([eE][-+][0-9]+)?
    (c) => {
      if (!c.lit('.')) return false;
      if (c.run(DIGITS + '_', 1) === null) return false;
      return optionalExponent(c);
    },
    // [-+]?[0-9][0-9_]*(:[0-5]?[0-9])+\.[0-9_]*
    (c) => {
      sign(c);
      if (c.oneOf(DIGITS) === '') return false;
      c.run(DIGITS + '_', 0);
      if (!sexagesimal(c)) return false;
      if (!c.lit('.')) return false;
      c.run(DIGITS + '_', 0);
      return true;
    },
    // [-+]?\.(inf|Inf|INF)
    (c) => {
      sign(c);
      if (!c.lit('.')) return false;
      return c.lit('inf') || c.lit('Inf') || c.lit('INF');
    },
    // \.(nan|NaN|NAN)
    (c) => {
      if (!c.lit('.')) return false;
      return c.lit('nan') || c.lit('NaN') || c.lit('NAN');
    },
  ]);
}

// Returns the timestamp fields, or null when `value` is not a timestamp.
export function matchTimestamp(value) {
  const c = new Cursor(value);
  const year = c.run(DIGITS, 4, 4);
  if (year === null || !c.lit('-')) return null;
  const month = c.run(DIGITS, 1, 2);
  if (month === null || !c.lit('-')) return null;
  const day = c.run(DIGITS, 1, 2);
  if (day === null) return null;

  const fields = {
    year, month, day,
    hour: null, minute: null, second: null,
    fraction: null, tz: null, tzSign: null, tzHour: null, tzMinute: null,
  };

  if (c.atEnd) {
    // A plain date, but only with a fully padded month and day.
    return month.length === 2 && day.length === 2 ? fields : null;
  }

  // (?:[Tt]|[ \t]+)
  if (c.oneOf('Tt') === '' && c.run(' \t', 1) === null) return null;
  fields.hour = c.run(DIGITS, 1, 2);
  if (fields.hour === null || !c.lit(':')) return null;
  fields.minute = c.run(DIGITS, 2, 2);
  if (fields.minute === null || !c.lit(':')) return null;
  fields.second = c.run(DIGITS, 2, 2);
  if (fields.second === null) return null;
  if (c.lit('.')) fields.fraction = c.run(DIGITS, 0) ?? '';

  const mark = c.i;
  c.run(' \t', 0);
  if (c.lit('Z')) {
    fields.tz = 'Z';
  } else {
    const tzSign = c.oneOf('-+');
    if (tzSign === '') {
      c.i = mark;
    } else {
      const tzHour = c.run(DIGITS, 1, 2);
      if (tzHour === null) return null;
      fields.tzSign = tzSign;
      fields.tzHour = tzHour;
      fields.tz = tzSign + tzHour;
      const inner = c.i;
      if (c.lit(':')) {
        const tzMinute = c.run(DIGITS, 2, 2);
        if (tzMinute === null) c.i = inner;
        else fields.tzMinute = tzMinute;
      }
    }
  }
  return c.atEnd ? fields : null;
}

// Ordered exactly as PyYAML registers them; the first-character index only
// filters candidates, it never reorders them.
const IMPLICIT_RESOLVERS = [
  { tag: 'tag:yaml.org,2002:bool', first: 'yYnNtTfFoO', empty: false, match: matchBool },
  { tag: 'tag:yaml.org,2002:float', first: '-+0123456789.', empty: false, match: matchFloat },
  { tag: 'tag:yaml.org,2002:int', first: '-+0123456789', empty: false, match: matchInt },
  { tag: 'tag:yaml.org,2002:merge', first: '<', empty: false, match: matchMerge },
  { tag: 'tag:yaml.org,2002:null', first: '~nN', empty: true, match: matchNull },
  {
    tag: 'tag:yaml.org,2002:timestamp',
    first: DIGITS,
    empty: false,
    match: (value) => matchTimestamp(value) !== null,
  },
  { tag: 'tag:yaml.org,2002:value', first: '=', empty: false, match: matchValue },
  { tag: 'tag:yaml.org,2002:yaml', first: '!&*', empty: false, match: matchYaml },
];

export const DEFAULT_SCALAR_TAG = 'tag:yaml.org,2002:str';
export const DEFAULT_SEQUENCE_TAG = 'tag:yaml.org,2002:seq';
export const DEFAULT_MAPPING_TAG = 'tag:yaml.org,2002:map';

// `kind` is 'scalar', 'sequence' or 'mapping'.
export function resolve(kind, value, implicit) {
  if (kind === 'scalar' && implicit[0]) {
    for (const resolver of IMPLICIT_RESOLVERS) {
      const applies = value === ''
        ? resolver.empty
        : resolver.first.includes(value[0]);
      if (applies && resolver.match(value)) return resolver.tag;
    }
  }
  if (kind === 'scalar') return DEFAULT_SCALAR_TAG;
  if (kind === 'sequence') return DEFAULT_SEQUENCE_TAG;
  return DEFAULT_MAPPING_TAG;
}

