// Implicit tag resolution (yaml.resolver.Resolver) for YAML 1.1.
// The resolvers PyYAML expresses as regular expressions are hand-written
// character scanners here.

const DIGITS = '0123456789';
const HEX = '0123456789abcdefABCDEF';

// A cursor over the scalar being tested.
class Cursor {
  constructor(text) {
    this.text = text;
    this.i = 0;
  }

  get atEnd() {
    return this.i >= this.text.length;
  }

  peek() {
    return this.i < this.text.length ? this.text[this.i] : '';
  }

  // Consumes `literal` if present.
  lit(literal) {
    if (this.text.startsWith(literal, this.i)) {
      this.i += literal.length;
      return true;
    }
    return false;
  }

  // Consumes one character from `set`.
  oneOf(set) {
    const ch = this.peek();
    if (ch !== '' && set.includes(ch)) {
      this.i += 1;
      return ch;
    }
    return '';
  }

  // Consumes between `min` and `max` characters from `set`; returns the run or
  // null when fewer than `min` are available.
  run(set, min, max = Infinity) {
    const start = this.i;
    while (this.i < this.text.length && set.includes(this.text[this.i])) {
      if (this.i - start >= max) break;
      this.i += 1;
    }
    if (this.i - start < min) {
      this.i = start;
      return null;
    }
    return this.text.slice(start, this.i);
  }
}

function tryAlternatives(value, alternatives) {
  for (const alternative of alternatives) {
    const cursor = new Cursor(value);
    if (alternative(cursor) && cursor.atEnd) return true;
  }
  return false;
}

const BOOL_VALUES = new Set([
  'yes', 'Yes', 'YES', 'no', 'No', 'NO',
  'true', 'True', 'TRUE', 'false', 'False', 'FALSE',
  'on', 'On', 'ON', 'off', 'Off', 'OFF',
]);

