// Python's datetime.date / datetime.datetime construction rules, including the
// ValueError messages raised for out-of-range fields.

import { PyValueError } from './errors.mjs';
import { PyDate, PyDateTime } from './pytypes.mjs';

const DAYS_IN_MONTH = [0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];

function isLeapYear(year) {
  return year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
}

function daysInMonth(year, month) {
  if (month === 2 && isLeapYear(year)) return 29;
  return DAYS_IN_MONTH[month];
}

function checkDateFields(year, month, day) {
  if (year < 1 || year > 9999) {
    throw new PyValueError(`year ${year} is out of range`);
  }
  if (month < 1 || month > 12) {
    throw new PyValueError('month must be in 1..12');
  }
  const limit = daysInMonth(year, month);
  if (day < 1 || day > limit) {
    throw new PyValueError('day is out of range for month');
  }
}

function checkTimeFields(hour, minute, second, microsecond) {
  if (hour < 0 || hour > 23) throw new PyValueError('hour must be in 0..23');
  if (minute < 0 || minute > 59) throw new PyValueError('minute must be in 0..59');
  if (second < 0 || second > 59) throw new PyValueError('second must be in 0..59');
  if (microsecond < 0 || microsecond > 999999) {
    throw new PyValueError('microsecond must be in 0..999999');
  }
}

export function makeDate(year, month, day) {
  checkDateFields(year, month, day);
  return new PyDate(year, month, day);
}

export function makeDateTime(
  year, month, day, hour, minute, second, microsecond, offsetMinutes
) {
  checkDateFields(year, month, day);
  checkTimeFields(hour, minute, second, microsecond);
  if (offsetMinutes !== null && Math.abs(offsetMinutes) >= 24 * 60) {
    throw new PyValueError(
      'offset must be a timedelta strictly between -timedelta(hours=24) and ' +
        'timedelta(hours=24), not ' + timedeltaRepr(offsetMinutes) + '.'
    );
  }
  return new PyDateTime(
    year, month, day, hour, minute, second, microsecond, offsetMinutes
  );
}

function timedeltaRepr(minutes) {
  const days = Math.floor(minutes / (24 * 60));
  const seconds = (minutes - days * 24 * 60) * 60;
  const parts = [];
  if (days) parts.push(`days=${days}`);
  if (seconds) parts.push(`seconds=${seconds}`);
  return `datetime.timedelta(${parts.join(', ') || '0'})`;
}

