// Base64 for the !!binary tag, matching base64.decodebytes / encodebytes.

const ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';

const REVERSE = new Map();
for (let i = 0; i < ALPHABET.length; i += 1) REVERSE.set(ALPHABET[i], i);

export class BinasciiError extends Error {}

// binascii.a2b_base64 discards characters outside the alphabet and stops at
// the first padding, but still validates the length of the data it collected.
export function decodeBase64(text) {
  let data = '';
  for (const ch of text) {
    if (ch === '=') break;
    if (REVERSE.has(ch)) data += ch;
  }
  if (data.length % 4 === 1) {
    throw new BinasciiError(
      `Invalid base64-encoded string: number of data characters (${data.length}) cannot be 1 more than a multiple of 4`
    );
  }
  const bytes = [];
  let bits = 0;
  let accumulator = 0;
  for (const ch of data) {
    accumulator = (accumulator << 6) | REVERSE.get(ch);
    bits += 6;
    if (bits >= 8) {
      bits -= 8;
      bytes.push((accumulator >> bits) & 0xff);
    }
  }
  return new Uint8Array(bytes);
}

// base64.encodebytes: 76-character lines, each terminated by a newline.
export function encodeBase64(bytes) {
  let out = '';
  for (let i = 0; i < bytes.length; i += 3) {
    const remaining = bytes.length - i;
    const b0 = bytes[i];
    const b1 = remaining > 1 ? bytes[i + 1] : 0;
    const b2 = remaining > 2 ? bytes[i + 2] : 0;
    out += ALPHABET[b0 >> 2];
    out += ALPHABET[((b0 & 0x03) << 4) | (b1 >> 4)];
    out += remaining > 1 ? ALPHABET[((b1 & 0x0f) << 2) | (b2 >> 6)] : '=';
    out += remaining > 2 ? ALPHABET[b2 & 0x3f] : '=';
  }
  let wrapped = '';
  for (let i = 0; i < out.length; i += 76) {
    wrapped += out.slice(i, i + 76) + '\n';
  }
  return wrapped;
}

