// Node graph -> Python values, a transliteration of yaml.constructor.SafeConstructor.

import { ConstructorError } from './errors.mjs';
import { BinasciiError, decodeBase64 } from './base64.mjs';
import { Composer } from './composer.mjs';
import { MappingNode, ScalarNode, SequenceNode } from './nodes.mjs';
import { makeDate, makeDateTime } from './pydatetime.mjs';
import { pyRepr } from './pyrepr.mjs';
import {
  PY_NONE,
  PyDict,
  PySet,
  PyTuple,
  Unhashable,
  typeName,
} from './pytypes.mjs';
import { matchTimestamp } from './resolver.mjs';

const TAG = 'tag:yaml.org,2002:';

const BOOL_VALUES = new Map([
  ['yes', true],
  ['no', false],
  ['true', true],
  ['false', false],
  ['on', true],
  ['off', false],
]);

// Stands in for a Python constructor implemented as a generator: `value` is
// what the generator yields, `fill` runs the code after the yield.
class Deferred {
  constructor(value, fill) {
    this.value = value;
    this.fill = fill;
  }
}

function stripUnderscores(text) {
  let out = '';
  for (const ch of text) if (ch !== '_') out += ch;
  return out;
}

function parseBigInt(digits, base) {
  let value = 0n;
  const big = BigInt(base);
  for (const ch of digits) {
    const digit = BigInt(Number.parseInt(ch, base));
    value = value * big + digit;
  }
  return value;
}

export class SafeConstructor extends Composer {
  constructor(text) {
    super(text);
    this.constructedObjects = new Map();
    this.recursiveObjects = new Map();
    this.stateGenerators = [];
    this.deepConstruct = false;
  }

  // -------------------------------------------------------------- public API

  getSingleData() {
    const node = this.getSingleNode();
    if (node !== null) return this.constructDocument(node);
    return PY_NONE;
  }

  constructDocument(node) {
    const data = this.constructObject(node);
    while (this.stateGenerators.length) {
      const generators = this.stateGenerators;
      this.stateGenerators = [];
      for (const generator of generators) generator.fill();
    }
    this.constructedObjects = new Map();
    this.recursiveObjects = new Map();
    this.deepConstruct = false;
    return data;
  }

  constructObject(node, deep = false) {
    if (this.constructedObjects.has(node)) {
      return this.constructedObjects.get(node);
    }
    let oldDeep;
    if (deep) {
      oldDeep = this.deepConstruct;
      this.deepConstruct = true;
    }
    if (this.recursiveObjects.has(node)) {
      throw new ConstructorError(
        null,
        null,
        'found unconstructable recursive node',
        node.startMark
      );
    }
    this.recursiveObjects.set(node, null);
    let data = this.callConstructor(node);
    if (data instanceof Deferred) {
      const deferred = data;
      data = deferred.value;
      if (this.deepConstruct) deferred.fill();
      else this.stateGenerators.push(deferred);
    }
    this.constructedObjects.set(node, data);
    this.recursiveObjects.delete(node);
    if (deep) this.deepConstruct = oldDeep;
    return data;
  }

  callConstructor(node) {
    switch (node.tag) {
      case TAG + 'null':
        return this.constructYamlNull(node);
      case TAG + 'bool':
        return this.constructYamlBool(node);
      case TAG + 'int':
        return this.constructYamlInt(node);
      case TAG + 'float':
        return this.constructYamlFloat(node);
      case TAG + 'binary':
        return this.constructYamlBinary(node);
      case TAG + 'timestamp':
        return this.constructYamlTimestamp(node);
      case TAG + 'omap':
        return this.constructYamlOmap(node);
      case TAG + 'pairs':
        return this.constructYamlPairs(node);
      case TAG + 'set':
        return this.constructYamlSet(node);
      case TAG + 'str':
        return this.constructYamlStr(node);
      case TAG + 'seq':
        return this.constructYamlSeq(node);
      case TAG + 'map':
        return this.constructYamlMap(node);
      default:
        return this.constructUndefined(node);
    }
  }

  constructUndefined(node) {
    throw new ConstructorError(
      null,
      null,
      `could not determine a constructor for the tag ${pyRepr(node.tag)}`,
      node.startMark
    );
  }

  // ------------------------------------------------------------- collections

  constructScalar(node) {
    if (node instanceof MappingNode) {
      for (const [keyNode, valueNode] of node.value) {
        if (keyNode.tag === TAG + 'value') return this.constructScalar(valueNode);
      }
    }
    if (!(node instanceof ScalarNode)) {
      throw new ConstructorError(
        null,
        null,
        `expected a scalar node, but found ${node.id}`,
        node.startMark
      );
    }
    return node.value;
  }

  constructSequence(node, deep = false) {
    if (!(node instanceof SequenceNode)) {
      throw new ConstructorError(
        null,
        null,
        `expected a sequence node, but found ${node.id}`,
        node.startMark
      );
    }
    return node.value.map((child) => this.constructObject(child, deep));
  }

  constructMapping(node, deep = false) {
    if (node instanceof MappingNode) this.flattenMapping(node);
    if (!(node instanceof MappingNode)) {
      throw new ConstructorError(
        null,
        null,
        `expected a mapping node, but found ${node.id}`,
        node.startMark
      );
    }
    const mapping = new PyDict();
    for (const [keyNode, valueNode] of node.value) {
      const key = this.constructObject(keyNode, deep);
      if (!isHashable(key)) {
        throw new ConstructorError(
          'while constructing a mapping',
          node.startMark,
          'found unhashable key',
          keyNode.startMark
        );
      }
      const value = this.constructObject(valueNode, deep);
      try {
        mapping.set(key, value);
      } catch (err) {
        if (err instanceof Unhashable) {
          throw new ConstructorError(
            'while constructing a mapping',
            node.startMark,
            'found unhashable key',
            keyNode.startMark
          );
        }
        throw err;
      }
    }
    return mapping;
  }

  constructPairs(node, deep = false) {
    if (!(node instanceof MappingNode)) {
      throw new ConstructorError(
        null,
        null,
        `expected a mapping node, but found ${node.id}`,
        node.startMark
      );
    }
    const pairs = [];
    for (const [keyNode, valueNode] of node.value) {
      pairs.push([
        this.constructObject(keyNode, deep),
        this.constructObject(valueNode, deep),
      ]);
    }
    return pairs;
  }

  flattenMapping(node) {
    let merge = [];
    let index = 0;
    while (index < node.value.length) {
      const [keyNode, valueNode] = node.value[index];
      if (keyNode.tag === TAG + 'merge') {
        node.value.splice(index, 1);
        if (valueNode instanceof MappingNode) {
          this.flattenMapping(valueNode);
          merge = merge.concat(valueNode.value);
        } else if (valueNode instanceof SequenceNode) {
          const submerge = [];
          for (const subnode of valueNode.value) {
            if (!(subnode instanceof MappingNode)) {
              throw new ConstructorError(
                'while constructing a mapping',
                node.startMark,
                `expected a mapping for merging, but found ${subnode.id}`,
                subnode.startMark
              );
            }
            this.flattenMapping(subnode);
            submerge.push(subnode.value);
          }
          submerge.reverse();
          for (const value of submerge) merge = merge.concat(value);
        } else {
          throw new ConstructorError(
            'while constructing a mapping',
            node.startMark,
            'expected a mapping or list of mappings for merging, but found ' +
              valueNode.id,
            valueNode.startMark
          );
        }
      } else if (keyNode.tag === TAG + 'value') {
        keyNode.tag = TAG + 'str';
        index += 1;
      } else {
        index += 1;
      }
    }
    if (merge.length) node.value = merge.concat(node.value);
  }

  // ----------------------------------------------------------------- scalars

  constructYamlNull(node) {
    this.constructScalar(node);
    return PY_NONE;
  }

  constructYamlBool(node) {
    const value = this.constructScalar(node);
    return BOOL_VALUES.get(value.toLowerCase());
  }

  constructYamlInt(node) {
    let value = stripUnderscores(this.constructScalar(node));
    let sign = 1n;
    if (value[0] === '-') sign = -1n;
    if (value[0] === '+' || value[0] === '-') value = value.slice(1);
    if (value === '0') return 0n;
    if (value.startsWith('0b')) return sign * parseBigInt(value.slice(2), 2);
    if (value.startsWith('0x')) return sign * parseBigInt(value.slice(2), 16);
    if (value[0] === '0') return sign * parseBigInt(value, 8);
    if (value.includes(':')) {
      const digits = value.split(':').map((part) => BigInt(part));
      digits.reverse();
      let base = 1n;
      let total = 0n;
      for (const digit of digits) {
        total += digit * base;
        base *= 60n;
      }
      return sign * total;
    }
    return sign * BigInt(value);
  }

  constructYamlFloat(node) {
    let value = stripUnderscores(this.constructScalar(node)).toLowerCase();
    let sign = 1;
    if (value[0] === '-') sign = -1;
    if (value[0] === '+' || value[0] === '-') value = value.slice(1);
    if (value === '.inf') return sign * Infinity;
    if (value === '.nan') return NaN;
    if (value.includes(':')) {
      const digits = value.split(':').map((part) => Number(part));
      digits.reverse();
      let base = 1;
      let total = 0;
      for (const digit of digits) {
        total += digit * base;
        base *= 60;
      }
      return sign * total;
    }
    return sign * Number(value);
  }

  constructYamlBinary(node) {
    const value = this.constructScalar(node);
    for (const ch of value) {
      if (ch.codePointAt(0) > 0x7f) {
        throw new ConstructorError(
          null,
          null,
          'failed to convert base64 data into ascii: ' +
            "'ascii' codec can't encode character " +
            pyRepr(ch) +
            ' in position ' +
            value.indexOf(ch) +
            ': ordinal not in range(128)',
          node.startMark
        );
      }
    }
    try {
      return decodeBase64(value);
    } catch (err) {
      if (err instanceof BinasciiError) {
        throw new ConstructorError(
          null,
          null,
          `failed to decode base64 data: ${err.message}`,
          node.startMark
        );
      }
      throw err;
    }
  }

  constructYamlTimestamp(node) {
    const value = this.constructScalar(node);
    const fields = matchTimestamp(value, true);
    const year = Number.parseInt(fields.year, 10);
    const month = Number.parseInt(fields.month, 10);
    const day = Number.parseInt(fields.day, 10);
    if (!fields.hour) return makeDate(year, month, day);
    const hour = Number.parseInt(fields.hour, 10);
    const minute = Number.parseInt(fields.minute, 10);
    const second = Number.parseInt(fields.second, 10);
    let fraction = 0;
    let offset = null;
    if (fields.fraction) {
      let digits = fields.fraction.slice(0, 6);
      while (digits.length < 6) digits += '0';
      fraction = Number.parseInt(digits, 10);
      if (
        fields.fraction.length > 6 &&
        Number.parseInt(fields.fraction[6], 10) > 4
      ) {
        fraction += 1;
      }
    }
    if (fields.tzSign) {
      const tzHour = Number.parseInt(fields.tzHour, 10);
      const tzMinute = fields.tzMinute ? Number.parseInt(fields.tzMinute, 10) : 0;
      offset = tzHour * 60 + tzMinute;
      if (fields.tzSign === '-') offset = -offset;
    } else if (fields.tz) {
      offset = 0;
    }
    return makeDateTime(year, month, day, hour, minute, second, fraction, offset);
  }

  constructYamlStr(node) {
    return this.constructScalar(node);
  }

  // --------------------------------------------------- deferred constructors

  constructYamlSeq(node) {
    const data = [];
    return new Deferred(data, () => {
      for (const item of this.constructSequence(node)) data.push(item);
    });
  }

  constructYamlMap(node) {
    const data = new PyDict();
    return new Deferred(data, () => {
      data.update(this.constructMapping(node));
    });
  }

