    return new Deferred(data, () => {
      for (const key of this.constructMapping(node).keys()) data.add(key);
    });
  }

  constructYamlOmap(node) {
    const omap = [];
    return new Deferred(omap, () => {
      this.fillPairList(node, omap, 'while constructing an ordered map');
    });
  }

  constructYamlPairs(node) {
    const pairs = [];
