// YAML output, a transliteration of yaml.emitter.Emitter.
// All string indexing is done over code-point arrays so that column counting
// and slicing match Python's str semantics.

import { EmitterError } from './errors.mjs';
import {
  AliasEvent,
  CollectionEndEvent,
  CollectionStartEvent,
  DocumentEndEvent,
  DocumentStartEvent,
  MappingEndEvent,
  MappingStartEvent,
  ScalarEvent,
  SequenceEndEvent,
  SequenceStartEvent,
  StreamEndEvent,
  StreamStartEvent,
} from './events.mjs';
import { pyRepr } from './pyrepr.mjs';

const NEL = String.fromCharCode(0x85);
const LS = String.fromCharCode(0x2028);
const PS = String.fromCharCode(0x2029);
const NBSP = String.fromCharCode(0xa0);
const BOM = String.fromCharCode(0xfeff);
const BREAKS = '\n' + NEL + LS + PS;
const SPACE_BREAKS = ' ' + BREAKS;
const WHITESPACE = '\0 \t\r' + BREAKS;

const DEFAULT_TAG_PREFIXES = new Map([
  ['!', '!'],
  ['tag:yaml.org,2002:', '!!'],
]);

const ESCAPE_REPLACEMENTS = new Map([
  ['\0', '0'],
  ['\x07', 'a'],
  ['\x08', 'b'],
  ['\t', 't'],
  ['\n', 'n'],
  ['\x0b', 'v'],
  ['\x0c', 'f'],
  ['\r', 'r'],
  ['\x1b', 'e'],
  ['"', '"'],
  ['\\', '\\'],
  [NEL, 'N'],
  [NBSP, '_'],
  [LS, 'L'],
  [PS, 'P'],
]);

class ScalarAnalysis {
  constructor(fields) {
    Object.assign(this, fields);
  }
}

function codePoints(text) {
  return Array.from(text);
}

function hexUpper(code, width) {
  let s = code.toString(16).toUpperCase();
  while (s.length < width) s = '0' + s;
  return s;
}

export class Emitter {
  constructor(options = {}) {
    this.chunks = [];
    this.states = [];
    this.state = 'expectStreamStart';
    this.events = [];
    this.event = null;
    this.indents = [];
    this.indent = null;
    this.flowLevel = 0;
    this.rootContext = false;
    this.sequenceContext = false;
    this.mappingContext = false;
    this.simpleKeyContext = false;
    this.line = 0;
    this.column = 0;
    this.whitespace = true;
    this.indention = true;
    this.openEnded = false;
    this.canonical = options.canonical ?? false;
    this.allowUnicode = options.allowUnicode ?? false;
    this.bestIndent = 2;
    if (options.indent && options.indent > 1 && options.indent < 10) {
      this.bestIndent = options.indent;
    }
    this.bestWidth = 80;
    if (options.width && options.width > this.bestIndent * 2) {
      this.bestWidth = options.width;
    }
    this.bestLineBreak = '\n';
    if (['\r', '\n', '\r\n'].includes(options.lineBreak)) {
      this.bestLineBreak = options.lineBreak;
    }
    this.tagPrefixes = null;
    this.preparedAnchor = null;
    this.preparedTag = null;
    this.analysis = null;
    this.style = null;
  }

  getValue() {
    return this.chunks.join('');
  }

  write(data) {
    this.chunks.push(data);
  }

  // ----------------------------------------------------------- event pipeline

  emit(event) {
    this.events.push(event);
    while (!this.needMoreEvents()) {
      this.event = this.events.shift();
      this[this.state]();
      this.event = null;
    }
  }

  needMoreEvents() {
    if (this.events.length === 0) return true;
    const event = this.events[0];
    if (event instanceof DocumentStartEvent) return this.needEvents(1);
    if (event instanceof SequenceStartEvent) return this.needEvents(2);
    if (event instanceof MappingStartEvent) return this.needEvents(3);
    return false;
  }

  needEvents(count) {
    let level = 0;
    for (const event of this.events.slice(1)) {
      if (event instanceof DocumentStartEvent || event instanceof CollectionStartEvent) {
        level += 1;
      } else if (event instanceof DocumentEndEvent || event instanceof CollectionEndEvent) {
        level -= 1;
      } else if (event instanceof StreamEndEvent) {
        level = -1;
      }
      if (level < 0) return false;
    }
    return this.events.length < count + 1;
  }

  increaseIndent(flow = false, indentless = false) {
    this.indents.push(this.indent);
    if (this.indent === null) {
      this.indent = flow ? this.bestIndent : 0;
    } else if (!indentless) {
      this.indent += this.bestIndent;
    }
  }

  // ------------------------------------------------------------ stream states

  expectStreamStart() {
    if (this.event instanceof StreamStartEvent) {
      this.state = 'expectFirstDocumentStart';
    } else {
      throw new EmitterError('expected StreamStartEvent, but got an other event');
    }
  }

  expectNothing() {
    throw new EmitterError('expected nothing, but got an other event');
  }

  expectFirstDocumentStart() {
    return this.expectDocumentStart(true);
  }

  expectDocumentStart(first = false) {
    if (this.event instanceof DocumentStartEvent) {
      if ((this.event.version || this.event.tags) && this.openEnded) {
        this.writeIndicator('...', true);
        this.writeIndent();
      }
      if (this.event.version) {
        this.writeVersionDirective(this.prepareVersion(this.event.version));
      }
      this.tagPrefixes = new Map(DEFAULT_TAG_PREFIXES);
      if (this.event.tags) {
        const handles = Array.from(this.event.tags.keys()).sort();
        for (const handle of handles) {
          const prefix = this.event.tags.get(handle);
          this.tagPrefixes.set(prefix, handle);
          this.writeTagDirective(
            this.prepareTagHandle(handle),
            this.prepareTagPrefix(prefix)
          );
        }
      }
      const implicit =
        first &&
        !this.event.explicit &&
        !this.canonical &&
        !this.event.version &&
        !this.event.tags &&
        !this.checkEmptyDocument();
      if (!implicit) {
        this.writeIndent();
        this.writeIndicator('---', true);
        if (this.canonical) this.writeIndent();
      }
      this.state = 'expectDocumentRoot';
    } else if (this.event instanceof StreamEndEvent) {
      if (this.openEnded) {
        this.writeIndicator('...', true);
        this.writeIndent();
      }
      this.state = 'expectNothing';
    } else {
      throw new EmitterError('expected DocumentStartEvent, but got an other event');
    }
  }

  expectDocumentEnd() {
    if (this.event instanceof DocumentEndEvent) {
      this.writeIndent();
      if (this.event.explicit) {
        this.writeIndicator('...', true);
        this.writeIndent();
      }
      this.state = 'expectDocumentStart';
    } else {
      throw new EmitterError('expected DocumentEndEvent, but got an other event');
    }
  }

  expectDocumentRoot() {
    this.states.push('expectDocumentEnd');
    this.expectNode(true);
  }

  // -------------------------------------------------------------- node states

  expectNode(root = false, sequence = false, mapping = false, simpleKey = false) {
    this.rootContext = root;
    this.sequenceContext = sequence;
    this.mappingContext = mapping;
    this.simpleKeyContext = simpleKey;
    if (this.event instanceof AliasEvent) {
      this.expectAlias();
    } else if (
      this.event instanceof ScalarEvent ||
      this.event instanceof CollectionStartEvent
    ) {
      this.processAnchor('&');
      this.processTag();
      if (this.event instanceof ScalarEvent) {
        this.expectScalar();
      } else if (this.event instanceof SequenceStartEvent) {
        if (
          this.flowLevel ||
          this.canonical ||
          this.event.flowStyle ||
          this.checkEmptySequence()
        ) {
          this.expectFlowSequence();
        } else {
          this.expectBlockSequence();
        }
      } else if (this.event instanceof MappingStartEvent) {
        if (
          this.flowLevel ||
          this.canonical ||
          this.event.flowStyle ||
          this.checkEmptyMapping()
        ) {
          this.expectFlowMapping();
        } else {
          this.expectBlockMapping();
        }
      }
    } else {
      throw new EmitterError('expected NodeEvent, but got an other event');
    }
  }

  expectAlias() {
    if (this.event.anchor === null) {
      throw new EmitterError('anchor is not specified for alias');
    }
    this.processAnchor('*');
    this.state = this.states.pop();
  }

  expectScalar() {
    this.increaseIndent(true);
    this.processScalar();
    this.indent = this.indents.pop();
    this.state = this.states.pop();
  }

  // ----------------------------------------------------------- flow sequences

  expectFlowSequence() {
    this.writeIndicator('[', true, true);
    this.flowLevel += 1;
    this.increaseIndent(true);
    this.state = 'expectFirstFlowSequenceItem';
  }

  expectFirstFlowSequenceItem() {
    if (this.event instanceof SequenceEndEvent) {
      this.indent = this.indents.pop();
      this.flowLevel -= 1;
      this.writeIndicator(']', false);
      this.state = this.states.pop();
    } else {
      if (this.canonical || this.column > this.bestWidth) this.writeIndent();
      this.states.push('expectFlowSequenceItem');
      this.expectNode(false, true);
    }
  }

  expectFlowSequenceItem() {
    if (this.event instanceof SequenceEndEvent) {
      this.indent = this.indents.pop();
      this.flowLevel -= 1;
      if (this.canonical) {
        this.writeIndicator(',', false);
        this.writeIndent();
      }
      this.writeIndicator(']', false);
      this.state = this.states.pop();
    } else {
      this.writeIndicator(',', false);
      if (this.canonical || this.column > this.bestWidth) this.writeIndent();
      this.states.push('expectFlowSequenceItem');
      this.expectNode(false, true);
    }
  }

  // ------------------------------------------------------------ flow mappings

  expectFlowMapping() {
    this.writeIndicator('{', true, true);
    this.flowLevel += 1;
    this.increaseIndent(true);
    this.state = 'expectFirstFlowMappingKey';
  }

  expectFirstFlowMappingKey() {
    if (this.event instanceof MappingEndEvent) {
      this.indent = this.indents.pop();
      this.flowLevel -= 1;
      this.writeIndicator('}', false);
      this.state = this.states.pop();
    } else {
      if (this.canonical || this.column > this.bestWidth) this.writeIndent();
      if (!this.canonical && this.checkSimpleKey()) {
        this.states.push('expectFlowMappingSimpleValue');
        this.expectNode(false, false, true, true);
      } else {
        this.writeIndicator('?', true);
        this.states.push('expectFlowMappingValue');
        this.expectNode(false, false, true);
      }
    }
  }

  expectFlowMappingKey() {
    if (this.event instanceof MappingEndEvent) {
      this.indent = this.indents.pop();
      this.flowLevel -= 1;
      if (this.canonical) {
        this.writeIndicator(',', false);
        this.writeIndent();
      }
      this.writeIndicator('}', false);
      this.state = this.states.pop();
    } else {
      this.writeIndicator(',', false);
      if (this.canonical || this.column > this.bestWidth) this.writeIndent();
      if (!this.canonical && this.checkSimpleKey()) {
        this.states.push('expectFlowMappingSimpleValue');
        this.expectNode(false, false, true, true);
      } else {
        this.writeIndicator('?', true);
        this.states.push('expectFlowMappingValue');
        this.expectNode(false, false, true);
      }
    }
  }

  expectFlowMappingSimpleValue() {
    this.writeIndicator(':', false);
    this.states.push('expectFlowMappingKey');
    this.expectNode(false, false, true);
  }

  expectFlowMappingValue() {
    if (this.canonical || this.column > this.bestWidth) this.writeIndent();
    this.writeIndicator(':', true);
    this.states.push('expectFlowMappingKey');
    this.expectNode(false, false, true);
  }

  // ---------------------------------------------------------- block sequences

  expectBlockSequence() {
    const indentless = this.mappingContext && !this.indention;
    this.increaseIndent(false, indentless);
    this.state = 'expectFirstBlockSequenceItem';
  }

  expectFirstBlockSequenceItem() {
    return this.expectBlockSequenceItem(true);
  }

  expectBlockSequenceItem(first = false) {
    if (!first && this.event instanceof SequenceEndEvent) {
      this.indent = this.indents.pop();
      this.state = this.states.pop();
    } else {
      this.writeIndent();
      this.writeIndicator('-', true, false, true);
      this.states.push('expectBlockSequenceItem');
      this.expectNode(false, true);
    }
  }

  // ----------------------------------------------------------- block mappings

  expectBlockMapping() {
    this.increaseIndent(false);
    this.state = 'expectFirstBlockMappingKey';
  }

  expectFirstBlockMappingKey() {
    return this.expectBlockMappingKey(true);
  }

  expectBlockMappingKey(first = false) {
    if (!first && this.event instanceof MappingEndEvent) {
      this.indent = this.indents.pop();
      this.state = this.states.pop();
    } else {
      this.writeIndent();
      if (this.checkSimpleKey()) {
        this.states.push('expectBlockMappingSimpleValue');
        this.expectNode(false, false, true, true);
      } else {
        this.writeIndicator('?', true, false, true);
        this.states.push('expectBlockMappingValue');
        this.expectNode(false, false, true);
      }
    }
  }

  expectBlockMappingSimpleValue() {
    this.writeIndicator(':', false);
    this.states.push('expectBlockMappingKey');
    this.expectNode(false, false, true);
  }

  expectBlockMappingValue() {
    this.writeIndent();
    this.writeIndicator(':', true, false, true);
    this.states.push('expectBlockMappingKey');
    this.expectNode(false, false, true);
  }

  // ---------------------------------------------------------------- checkers

  checkEmptySequence() {
    return (
      this.event instanceof SequenceStartEvent &&
      this.events.length > 0 &&
      this.events[0] instanceof SequenceEndEvent
    );
  }

  checkEmptyMapping() {
    return (
      this.event instanceof MappingStartEvent &&
      this.events.length > 0 &&
      this.events[0] instanceof MappingEndEvent
    );
  }

  checkEmptyDocument() {
    if (!(this.event instanceof DocumentStartEvent) || this.events.length === 0) {
      return false;
    }
    const event = this.events[0];
    return (
      event instanceof ScalarEvent &&
      event.anchor === null &&
      event.tag === null &&
      event.implicit &&
      event.value === ''
    );
  }

  checkSimpleKey() {
    let length = 0;
    if (this.event.anchor !== null && this.event.anchor !== undefined) {
      if (this.preparedAnchor === null) {
        this.preparedAnchor = this.prepareAnchor(this.event.anchor);
      }
      length += codePoints(this.preparedAnchor).length;
    }
    if (
      (this.event instanceof ScalarEvent ||
        this.event instanceof CollectionStartEvent) &&
      this.event.tag !== null &&
      this.event.tag !== undefined
    ) {
      if (this.preparedTag === null) {
        this.preparedTag = this.prepareTag(this.event.tag);
      }
      length += codePoints(this.preparedTag).length;
    }
    if (this.event instanceof ScalarEvent) {
      if (this.analysis === null) {
        this.analysis = this.analyzeScalar(this.event.value);
      }
      length += codePoints(this.analysis.scalar).length;
    }
    return (
      length < 128 &&
      (this.event instanceof AliasEvent ||
        (this.event instanceof ScalarEvent &&
          !this.analysis.empty &&
          !this.analysis.multiline) ||
        this.checkEmptySequence() ||
        this.checkEmptyMapping())
    );
  }

  // ------------------------------------------------- anchor, tag and scalar

  processAnchor(indicator) {
    if (this.event.anchor === null || this.event.anchor === undefined) {
      this.preparedAnchor = null;
      return;
    }
    if (this.preparedAnchor === null) {
      this.preparedAnchor = this.prepareAnchor(this.event.anchor);
    }
    if (this.preparedAnchor) {
      this.writeIndicator(indicator + this.preparedAnchor, true);
    }
    this.preparedAnchor = null;
  }

  processTag() {
    let tag = this.event.tag;
    if (this.event instanceof ScalarEvent) {
      if (this.style === null) this.style = this.chooseScalarStyle();
      if (
        (!this.canonical || tag === null) &&
        ((this.style === '' && this.event.implicit[0]) ||
          (this.style !== '' && this.event.implicit[1]))
      ) {
        this.preparedTag = null;
        return;
      }
      if (this.event.implicit[0] && tag === null) {
        tag = '!';
        this.preparedTag = null;
      }
    } else if ((!this.canonical || tag === null) && this.event.implicit) {
      this.preparedTag = null;
      return;
    }
    if (tag === null) throw new EmitterError('tag is not specified');
    if (this.preparedTag === null) this.preparedTag = this.prepareTag(tag);
    if (this.preparedTag) this.writeIndicator(this.preparedTag, true);
    this.preparedTag = null;
  }

  chooseScalarStyle() {
    if (this.analysis === null) this.analysis = this.analyzeScalar(this.event.value);
    if (this.event.style === '"' || this.canonical) return '"';
    if (!this.event.style && this.event.implicit[0]) {
      if (
        !(this.simpleKeyContext && (this.analysis.empty || this.analysis.multiline)) &&
        ((this.flowLevel && this.analysis.allowFlowPlain) ||
          (!this.flowLevel && this.analysis.allowBlockPlain))
      ) {
        return '';
      }
    }
    if (this.event.style && '|>'.includes(this.event.style)) {
      if (!this.flowLevel && !this.simpleKeyContext && this.analysis.allowBlock) {
        return this.event.style;
      }
    }
    if (!this.event.style || this.event.style === "'") {
      if (
        this.analysis.allowSingleQuoted &&
        !(this.simpleKeyContext && this.analysis.multiline)
      ) {
        return "'";
      }
    }
    return '"';
  }

  processScalar() {
    if (this.analysis === null) this.analysis = this.analyzeScalar(this.event.value);
    if (this.style === null) this.style = this.chooseScalarStyle();
    const split = !this.simpleKeyContext;
    if (this.style === '"') this.writeDoubleQuoted(this.analysis.scalar, split);
    else if (this.style === "'") this.writeSingleQuoted(this.analysis.scalar, split);
    else if (this.style === '>') this.writeFolded(this.analysis.scalar);
    else if (this.style === '|') this.writeLiteral(this.analysis.scalar);
    else this.writePlain(this.analysis.scalar, split);
    this.analysis = null;
    this.style = null;
  }

  // --------------------------------------------------------------- analyzers

  prepareVersion(version) {
    const [major, minor] = version;
    if (major !== 1) {
      throw new EmitterError(`unsupported YAML version: ${major}.${minor}`);
    }
    return `${major}.${minor}`;
  }

  prepareTagHandle(handle) {
    if (!handle) throw new EmitterError('tag handle must not be empty');
    if (handle[0] !== '!' || handle[handle.length - 1] !== '!') {
      throw new EmitterError(`tag handle must start and end with '!': ${pyRepr(handle)}`);
    }
    for (const ch of handle.slice(1, handle.length - 1)) {
      if (
        !(
          (ch >= '0' && ch <= '9') ||
          (ch >= 'A' && ch <= 'Z') ||
          (ch >= 'a' && ch <= 'z') ||
          '-_'.includes(ch)
        )
      ) {
        throw new EmitterError(
          `invalid character ${pyRepr(ch)} in the tag handle: ${pyRepr(handle)}`
        );
      }
    }
    return handle;
  }

  prepareTagPrefix(prefix) {
    if (!prefix) throw new EmitterError('tag prefix must not be empty');
    const chunks = [];
    const chars = codePoints(prefix);
    let start = 0;
    let end = chars[0] === '!' ? 1 : 0;
    while (end < chars.length) {
      const ch = chars[end];
      if (
        (ch >= '0' && ch <= '9') ||
        (ch >= 'A' && ch <= 'Z') ||
        (ch >= 'a' && ch <= 'z') ||
        "-;/?:@&=+$,_.~*'()[]".includes(ch)
      ) {
        end += 1;
      } else {
        if (start < end) chunks.push(chars.slice(start, end).join(''));
        start = end + 1;
        end = start;
        chunks.push(percentEncode(ch));
      }
    }
    if (start < end) chunks.push(chars.slice(start, end).join(''));
    return chunks.join('');
  }

  prepareTag(tag) {
    if (!tag) throw new EmitterError('tag must not be empty');
    if (tag === '!') return tag;
    let handle = null;
    let suffix = tag;
    const prefixes = Array.from(this.tagPrefixes.keys()).sort();
    for (const prefix of prefixes) {
      if (tag.startsWith(prefix) && (prefix === '!' || prefix.length < tag.length)) {
        handle = this.tagPrefixes.get(prefix);
        suffix = tag.slice(prefix.length);
      }
    }
    const chunks = [];
    const chars = codePoints(suffix);
    let start = 0;
    let end = 0;
    while (end < chars.length) {
      const ch = chars[end];
      if (
        (ch >= '0' && ch <= '9') ||
        (ch >= 'A' && ch <= 'Z') ||
        (ch >= 'a' && ch <= 'z') ||
        "-;/?:@&=+$,_.~*'()[]".includes(ch) ||
        (ch === '!' && handle !== '!')
      ) {
        end += 1;
      } else {
        if (start < end) chunks.push(chars.slice(start, end).join(''));
        start = end + 1;
        end = start;
        chunks.push(percentEncode(ch));
      }
    }
    if (start < end) chunks.push(chars.slice(start, end).join(''));
    const suffixText = chunks.join('');
    if (handle) return handle + suffixText;
    return `!<${suffixText}>`;
  }

  prepareAnchor(anchor) {
    if (!anchor) throw new EmitterError('anchor must not be empty');
    for (const ch of anchor) {
      if (
        !(
          (ch >= '0' && ch <= '9') ||
          (ch >= 'A' && ch <= 'Z') ||
          (ch >= 'a' && ch <= 'z') ||
          '-_'.includes(ch)
        )
      ) {
        throw new EmitterError(
          `invalid character ${pyRepr(ch)} in the anchor: ${pyRepr(anchor)}`
        );
      }
    }
    return anchor;
  }

  analyzeScalar(scalar) {
    if (scalar === '') {
      return new ScalarAnalysis({
        scalar,
        empty: true,
        multiline: false,
        allowFlowPlain: false,
        allowBlockPlain: true,
        allowSingleQuoted: true,
        allowDoubleQuoted: true,
        allowBlock: false,
      });
    }

    let blockIndicators = false;
    let flowIndicators = false;
    let lineBreaks = false;
    let specialCharacters = false;

    let leadingSpace = false;
    let leadingBreak = false;
    let trailingSpace = false;
    let trailingBreak = false;
    let breakSpace = false;
    let spaceBreak = false;

    if (scalar.startsWith('---') || scalar.startsWith('...')) {
      blockIndicators = true;
      flowIndicators = true;
    }

    const chars = codePoints(scalar);
    const size = chars.length;
    let precededByWhitespace = true;
    let followedByWhitespace = size === 1 || WHITESPACE.includes(chars[1]);
    let previousSpace = false;
    let previousBreak = false;

    let index = 0;
    while (index < size) {
      const ch = chars[index];

      if (index === 0) {
        if ("#,[]{}&*!|>'\"%@`".includes(ch)) {
          flowIndicators = true;
          blockIndicators = true;
        }
        if (ch === '?' || ch === ':') {
          flowIndicators = true;
          if (followedByWhitespace) blockIndicators = true;
        }
        if (ch === '-' && followedByWhitespace) {
          flowIndicators = true;
          blockIndicators = true;
        }
      } else {
        if (',?[]{}'.includes(ch)) flowIndicators = true;
        if (ch === ':') {
          flowIndicators = true;
          if (followedByWhitespace) blockIndicators = true;
        }
        if (ch === '#' && precededByWhitespace) {
          flowIndicators = true;
          blockIndicators = true;
        }
      }

      if (BREAKS.includes(ch)) lineBreaks = true;
      if (!(ch === '\n' || (ch >= '\x20' && ch <= '\x7e'))) {
        const code = ch.codePointAt(0);
        if (
          (code === 0x85 ||
            (code >= 0xa0 && code <= 0xd7ff) ||
            (code >= 0xe000 && code <= 0xfffd) ||
            (code >= 0x10000 && code < 0x10ffff)) &&
          ch !== BOM
        ) {
          if (!this.allowUnicode) specialCharacters = true;
        } else {
          specialCharacters = true;
        }
      }

      if (ch === ' ') {
        if (index === 0) leadingSpace = true;
        if (index === size - 1) trailingSpace = true;
        if (previousBreak) breakSpace = true;
        previousSpace = true;
        previousBreak = false;
      } else if (BREAKS.includes(ch)) {
        if (index === 0) leadingBreak = true;
        if (index === size - 1) trailingBreak = true;
        if (previousSpace) spaceBreak = true;
        previousSpace = false;
        previousBreak = true;
      } else {
        previousSpace = false;
        previousBreak = false;
      }

      index += 1;
      precededByWhitespace = WHITESPACE.includes(ch);
      followedByWhitespace =
        index + 1 >= size || WHITESPACE.includes(chars[index + 1]);
    }

    let allowFlowPlain = true;
    let allowBlockPlain = true;
    let allowSingleQuoted = true;
    const allowDoubleQuoted = true;
    let allowBlock = true;

    if (leadingSpace || leadingBreak || trailingSpace || trailingBreak) {
      allowFlowPlain = false;
      allowBlockPlain = false;
    }
    if (trailingSpace) allowBlock = false;
    if (breakSpace) {
      allowFlowPlain = false;
      allowBlockPlain = false;
      allowSingleQuoted = false;
    }
    if (spaceBreak || specialCharacters) {
      allowFlowPlain = false;
      allowBlockPlain = false;
      allowSingleQuoted = false;
      allowBlock = false;
    }
    if (lineBreaks) {
      allowFlowPlain = false;
      allowBlockPlain = false;
    }
    if (flowIndicators) allowFlowPlain = false;
    if (blockIndicators) allowBlockPlain = false;

    return new ScalarAnalysis({
      scalar,
      empty: false,
      multiline: lineBreaks,
      allowFlowPlain,
      allowBlockPlain,
      allowSingleQuoted,
      allowDoubleQuoted,
      allowBlock,
    });
  }

  // ----------------------------------------------------------------- writers

  writeIndicator(indicator, needWhitespace, whitespace = false, indention = false) {
    const data = this.whitespace || !needWhitespace ? indicator : ' ' + indicator;
    this.whitespace = whitespace;
    this.indention = this.indention && indention;
    this.column += codePoints(data).length;
    this.openEnded = false;
    this.write(data);
  }

  writeIndent() {
    const indent = this.indent || 0;
    if (
      !this.indention ||
      this.column > indent ||
      (this.column === indent && !this.whitespace)
    ) {
      this.writeLineBreak();
    }
    if (this.column < indent) {
      this.whitespace = true;
      const data = ' '.repeat(indent - this.column);
      this.column = indent;
      this.write(data);
    }
  }

  writeLineBreak(data = null) {
    const text = data === null ? this.bestLineBreak : data;
    this.whitespace = true;
    this.indention = true;
    this.line += 1;
    this.column = 0;
    this.write(text);
  }

  writeVersionDirective(versionText) {
    this.write(`%YAML ${versionText}`);
    this.writeLineBreak();
  }

  writeTagDirective(handleText, prefixText) {
    this.write(`%TAG ${handleText} ${prefixText}`);
    this.writeLineBreak();
  }

  // Block scalars.

  determineBlockHints(text) {
    let hints = '';
    if (text) {
      const chars = codePoints(text);
      if (SPACE_BREAKS.includes(chars[0])) hints += String(this.bestIndent);
      const last = chars[chars.length - 1];
      if (!BREAKS.includes(last)) hints += '-';
      else if (chars.length === 1 || BREAKS.includes(chars[chars.length - 2])) {
        hints += '+';
      }
    }
    return hints;
  }

  writeLiteral(text) {
    const hints = this.determineBlockHints(text);
    this.writeIndicator('|' + hints, true);
    if (hints.endsWith('+')) this.openEnded = true;
    this.writeLineBreak();
    const chars = codePoints(text);
    let breaks = true;
    let start = 0;
    let end = 0;
    while (end <= chars.length) {
      const ch = end < chars.length ? chars[end] : null;
      if (breaks) {
        if (ch === null || !BREAKS.includes(ch)) {
          for (const br of chars.slice(start, end)) {
            if (br === '\n') this.writeLineBreak();
            else this.writeLineBreak(br);
          }
          if (ch !== null) this.writeIndent();
          start = end;
        }
      } else if (ch === null || BREAKS.includes(ch)) {
        this.write(chars.slice(start, end).join(''));
        if (ch === null) this.writeLineBreak();
        start = end;
      }
      if (ch !== null) breaks = BREAKS.includes(ch);
      end += 1;
    }
  }

  writeFolded(text) {
    const hints = this.determineBlockHints(text);
    this.writeIndicator('>' + hints, true);
    if (hints.endsWith('+')) this.openEnded = true;
    this.writeLineBreak();
    const chars = codePoints(text);
    let leadingSpace = true;
    let spaces = false;
    let breaks = true;
    let start = 0;
    let end = 0;
    while (end <= chars.length) {
      const ch = end < chars.length ? chars[end] : null;
      if (breaks) {
        if (ch === null || !BREAKS.includes(ch)) {
          if (!leadingSpace && ch !== null && ch !== ' ' && chars[start] === '\n') {
            this.writeLineBreak();
          }
          leadingSpace = ch === ' ';
          for (const br of chars.slice(start, end)) {
            if (br === '\n') this.writeLineBreak();
            else this.writeLineBreak(br);
          }
          if (ch !== null) this.writeIndent();
          start = end;
        }
      } else if (spaces) {
        if (ch !== ' ') {
          if (start + 1 === end && this.column > this.bestWidth) {
            this.writeIndent();
          } else {
            const data = chars.slice(start, end).join('');
            this.column += codePoints(data).length;
            this.write(data);
          }
          start = end;
        }
      } else if (ch === null || SPACE_BREAKS.includes(ch)) {
        const data = chars.slice(start, end).join('');
        this.column += codePoints(data).length;
        this.write(data);
        if (ch === null) this.writeLineBreak();
        start = end;
      }
      if (ch !== null) {
        breaks = BREAKS.includes(ch);
        spaces = ch === ' ';
      }
      end += 1;
    }
  }

  writeSingleQuoted(text, split = true) {
    this.writeIndicator("'", true);
    const chars = codePoints(text);
    let spaces = false;
    let breaks = false;
    let start = 0;
    let end = 0;
    while (end <= chars.length) {
      const ch = end < chars.length ? chars[end] : null;
      if (spaces) {
        if (ch === null || ch !== ' ') {
          if (
            start + 1 === end &&
            this.column > this.bestWidth &&
            split &&
            start !== 0 &&
            end !== chars.length
          ) {
            this.writeIndent();
          } else {
            const data = chars.slice(start, end).join('');
            this.column += codePoints(data).length;
            this.write(data);
          }
          start = end;
        }
      } else if (breaks) {
        if (ch === null || !BREAKS.includes(ch)) {
          if (chars[start] === '\n') this.writeLineBreak();
          for (const br of chars.slice(start, end)) {
            if (br === '\n') this.writeLineBreak();
            else this.writeLineBreak(br);
          }
          this.writeIndent();
          start = end;
        }
      } else if (ch === null || SPACE_BREAKS.includes(ch) || ch === "'") {
        if (start < end) {
          const data = chars.slice(start, end).join('');
          this.column += codePoints(data).length;
          this.write(data);
          start = end;
        }
      }
      if (ch === "'") {
        this.column += 2;
        this.write("''");
        start = end + 1;
      }
      if (ch !== null) {
        spaces = ch === ' ';
        breaks = BREAKS.includes(ch);
      }
      end += 1;
    }
    this.writeIndicator("'", false);
  }

  writeDoubleQuoted(text, split = true) {
    this.writeIndicator('"', true);
    const chars = codePoints(text);
    let start = 0;
    let end = 0;
    while (end <= chars.length) {
      const ch = end < chars.length ? chars[end] : null;
      if (
        ch === null ||
        '"\\'.includes(ch) ||
        ch === NEL ||
        ch === LS ||
        ch === PS ||
        ch === BOM ||
        !(
          (ch >= '\x20' && ch <= '\x7e') ||
          (this.allowUnicode && isPrintableUnicode(ch))
        )
      ) {
        if (start < end) {
          const data = chars.slice(start, end).join('');
          this.column += codePoints(data).length;
          this.write(data);
          start = end;
        }
        if (ch !== null) {
          let data;
          const code = ch.codePointAt(0);
          if (ESCAPE_REPLACEMENTS.has(ch)) {
            data = '\\' + ESCAPE_REPLACEMENTS.get(ch);
          } else if (code <= 0xff) {
            data = '\\x' + hexUpper(code, 2);
          } else if (code <= 0xffff) {
            data = '\\u' + hexUpper(code, 4);
          } else {
            data = '\\U' + hexUpper(code, 8);
          }
          this.column += data.length;
          this.write(data);
          start = end + 1;
        }
      }
      if (
        end > 0 &&
        end < chars.length - 1 &&
        (ch === ' ' || start >= end) &&
        this.column + (end - start) > this.bestWidth &&
        split
      ) {
        const data = chars.slice(start, end).join('') + '\\';
        if (start < end) start = end;
        this.column += codePoints(data).length;
        this.write(data);
        this.writeIndent();
        this.whitespace = false;
        this.indention = false;
        if (chars[start] === ' ') {
          this.column += 1;
          this.write('\\');
        }
      }
      end += 1;
    }
    this.writeIndicator('"', false);
  }

  writePlain(text, split = true) {
    if (this.rootContext) this.openEnded = true;
    if (!text) return;
    if (!this.whitespace) {
      this.column += 1;
      this.write(' ');
    }
    this.whitespace = false;
    this.indention = false;
    const chars = codePoints(text);
    let spaces = false;
    let breaks = false;
    let start = 0;
    let end = 0;
    while (end <= chars.length) {
      const ch = end < chars.length ? chars[end] : null;
      if (spaces) {
        if (ch !== ' ') {
          if (start + 1 === end && this.column > this.bestWidth && split) {
            this.writeIndent();
            this.whitespace = false;
            this.indention = false;
          } else {
            const data = chars.slice(start, end).join('');
            this.column += codePoints(data).length;
            this.write(data);
          }
          start = end;
        }
      } else if (breaks) {
        if (ch === null || !BREAKS.includes(ch)) {
          if (chars[start] === '\n') this.writeLineBreak();
          for (const br of chars.slice(start, end)) {
            if (br === '\n') this.writeLineBreak();
            else this.writeLineBreak(br);
          }
          this.writeIndent();
          this.whitespace = false;
          this.indention = false;
          start = end;
        }
      } else if (ch === null || SPACE_BREAKS.includes(ch)) {
        const data = chars.slice(start, end).join('');
        this.column += codePoints(data).length;
        this.write(data);
        start = end;
      }
      if (ch !== null) {
        spaces = ch === ' ';
        breaks = BREAKS.includes(ch);
      }
      end += 1;
    }
  }
}

function isPrintableUnicode(ch) {
  const code = ch.codePointAt(0);
  return (
    (code >= 0xa0 && code <= 0xd7ff) || (code >= 0xe000 && code <= 0xfffd)
  );
}

function percentEncode(ch) {
  const bytes = new TextEncoder().encode(ch);
  let out = '';
  for (const byte of bytes) out += '%' + hexUpper(byte, 2);
  return out;
}

